-- BLURT keeps its small-room state under one row lock. Private relational
-- projections provide uniqueness, foreign keys, indexes and an audit history.
-- No application data is exposed through PostgREST or Realtime.
create schema if not exists blurt_private;
revoke all on schema blurt_private from public;
create table blurt_private.game_state (
 id integer primary key check (id=1), payload jsonb not null,
 updated_at timestamptz not null default now()
);
insert into blurt_private.game_state(id,payload) values(1,'{"players":{},"daily":{},"rooms":{}}');
create table blurt_private.players(id text primary key, display_name text not null, created_at timestamptz not null);
create table blurt_private.puzzles(id text primary key, canonical_answer text not null, category text not null, version int not null default 1, status text not null default 'active');
create table blurt_private.puzzle_answers(puzzle_id text references blurt_private.puzzles on delete cascade, normalized_answer text not null, primary key(puzzle_id,normalized_answer));
create table blurt_private.puzzle_assets(puzzle_id text references blurt_private.puzzles on delete cascade, stage_number int check(stage_number between 1 and 6), private_storage_key text not null unique, primary key(puzzle_id,stage_number));
create table blurt_private.daily_puzzles(day int primary key, puzzle_id text not null references blurt_private.puzzles, starts_at timestamptz not null, ends_at timestamptz not null);
create table blurt_private.daily_runs(id text primary key, day int not null references blurt_private.daily_puzzles, player_id text not null references blurt_private.players, status text not null, solved_stage int, unique(day,player_id));
create table blurt_private.daily_guesses(run_id text references blurt_private.daily_runs, stage_number int check(stage_number between 1 and 5), submitted_text text not null, correct boolean not null, idempotency_key text, primary key(run_id,stage_number), unique(run_id,idempotency_key));
create table blurt_private.rooms(code text primary key, host_player_id text not null references blurt_private.players, status text not null, settings jsonb not null, created_at timestamptz not null, expires_at timestamptz not null);
create index rooms_expiry on blurt_private.rooms(expires_at);
create table blurt_private.room_members(room_code text references blurt_private.rooms, player_id text references blurt_private.players, ready boolean not null, spectator boolean not null, points int not null check(points>=0), joined_at timestamptz not null, last_seen_at timestamptz not null, primary key(room_code,player_id));
create index members_player on blurt_private.room_members(player_id);
create table blurt_private.rounds(id text primary key, room_code text not null references blurt_private.rooms, puzzle_id text not null references blurt_private.puzzles, position int not null, starts_at timestamptz not null, ends_at timestamptz not null, reveal_at timestamptz);
create index rounds_room on blurt_private.rounds(room_code,starts_at);
create table blurt_private.party_guesses(round_id text references blurt_private.rounds, player_id text references blurt_private.players, stage_number int check(stage_number between 1 and 5), submitted_text text not null, correct boolean not null, idempotency_key text, primary key(round_id,player_id,stage_number), unique(round_id,player_id,idempotency_key));
create index party_guesses_player on blurt_private.party_guesses(player_id);

-- Atomically materialize the authoritative snapshot. Constraints fail the entire
-- transaction rather than permitting duplicate accepted guesses or scores.
create function blurt_private.project_state() returns trigger language plpgsql security invoker set search_path='' as $$
declare p jsonb; r jsonb; g jsonb; m jsonb; d jsonb; k text; runkey text; rid text;
begin
 for p in select value from jsonb_each(new.payload->'players') loop
  insert into blurt_private.players values(p->>'id',p->>'name',to_timestamp((p->>'created')::double precision/1000)) on conflict(id) do update set display_name=excluded.display_name;
 end loop;
 for k,r in select key,value from jsonb_each(new.payload->'daily') loop
  insert into blurt_private.daily_puzzles values((r->>'day')::int,r->>'puzzle',to_timestamp((r->>'day')::double precision*86400),to_timestamp(((r->>'day')::double precision+1)*86400)) on conflict do nothing;
  runkey=k;
  insert into blurt_private.daily_runs values(runkey,(r->>'day')::int,split_part(k,':',1),case when (r->>'done')::boolean then 'finished' else 'active' end,case when (r->>'solved')::boolean then jsonb_array_length(r->'guesses') else null end) on conflict(id) do update set status=excluded.status,solved_stage=excluded.solved_stage;
  for g in select value from jsonb_array_elements(r->'guesses') loop
   insert into blurt_private.daily_guesses values(runkey,(g->>'stage')::int,g->>'text',(g->>'correct')::boolean,g->>'key') on conflict(run_id,stage_number) do nothing;
  end loop;
 end loop;
 for r in select value from jsonb_each(new.payload->'rooms') loop
  insert into blurt_private.rooms values(r->>'code',r->>'host',r->>'status',jsonb_build_object('rounds',r->'rounds','duration',r->'duration','category',r->'category'),to_timestamp((r->>'created')::double precision/1000),to_timestamp((r->>'expires')::double precision/1000)) on conflict(code) do update set host_player_id=excluded.host_player_id,status=excluded.status,settings=excluded.settings;
  delete from blurt_private.room_members where room_code=r->>'code';
  for m in select value from jsonb_array_elements(r->'members') loop
   insert into blurt_private.room_members values(r->>'code',m->>'id',(m->>'ready')::boolean,(m->>'spectator')::boolean,(m->>'points')::int,to_timestamp((m->>'joined')::double precision/1000),to_timestamp((m->>'seen')::double precision/1000));
  end loop;
  d=r->'roundData';
  if d is not null and d<>'null'::jsonb then
   rid=(r->>'code')||':'||(d->>'starts');
   insert into blurt_private.rounds values(rid,r->>'code',d->>'puzzle',(r->>'round')::int,to_timestamp((d->>'starts')::double precision/1000),to_timestamp((d->>'ends')::double precision/1000),to_timestamp((d->>'revealAt')::double precision/1000)) on conflict(id) do update set reveal_at=excluded.reveal_at;
   for g in select value from jsonb_array_elements(d->'guesses') loop
    insert into blurt_private.party_guesses values(rid,g->>'player',(g->>'stage')::int,g->>'text',(g->>'correct')::boolean,g->>'key') on conflict(round_id,player_id,stage_number) do nothing;
   end loop;
  end if;
 end loop;
 new.updated_at=now();return new;
end $$;
create trigger project_state before update on blurt_private.game_state for each row execute function blurt_private.project_state();
revoke all on function blurt_private.project_state() from public;
do $$ declare t record; begin
 for t in select tablename from pg_tables where schemaname='blurt_private' loop
  execute format('alter table blurt_private.%I enable row level security',t.tablename);
 end loop;
end $$;
revoke all on all tables in schema blurt_private from public;

-- Isolated production state, durable scheduling and membership-authorized hints.
create table blurt_private.game_documents (
 scope text primary key check(length(scope)<120),
 payload jsonb not null check(jsonb_typeof(payload)='object'),
 revision bigint not null default 1,
 next_at timestamptz,
 updated_at timestamptz not null default now()
);
alter table blurt_private.game_documents enable row level security;
create index documents_due on blurt_private.game_documents(next_at) where next_at is not null;
create table blurt_private.rate_limits (
 actor text not null, bucket text not null, window_start bigint not null,
 count integer not null check(count>0), primary key(actor,bucket,window_start)
);
alter table blurt_private.rate_limits enable row level security;
create index rate_limit_expiry on blurt_private.rate_limits(window_start);
alter table blurt_private.players add column auth_user_id uuid unique references auth.users(id) on delete set null;
create table blurt_private.matches (
 id uuid primary key, room_code text not null references blurt_private.rooms(code),
 rules_snapshot jsonb not null, started_at timestamptz not null, finished_at timestamptz
);
alter table blurt_private.matches enable row level security;
create index matches_room on blurt_private.matches(room_code,started_at);
alter table blurt_private.rounds add column match_id uuid references blurt_private.matches(id);
create unique index rounds_match_position on blurt_private.rounds(match_id,position) where match_id is not null;
create table blurt_private.round_players (
 round_id text references blurt_private.rounds(id), player_id text references blurt_private.players(id),
 status text not null, solved_stage integer, points integer not null check(points between 0 and 500),
 primary key(round_id,player_id)
);
alter table blurt_private.round_players enable row level security;
create index round_players_player on blurt_private.round_players(player_id);

create function blurt_private.next_deadline(r jsonb) returns timestamptz
language plpgsql stable set search_path='' as $$
declare d jsonb; ms double precision := extract(epoch from now())*1000; target double precision; step double precision;
begin
 if (r->>'expires')::double precision<=ms then return now(); end if;
 if r->>'status'='finished' then return to_timestamp((r->>'expires')::double precision/1000); end if;
 if r->>'status'='lobby' then
  select min((x->>'seen')::double precision+45000) into target from jsonb_array_elements(r->'members') x where (x->>'seen')::double precision+45000>ms;
  return to_timestamp(least(coalesce(target,(r->>'expires')::double precision),(r->>'expires')::double precision)/1000);
 end if;
 d=r->'roundData';
 if d->>'revealAt' is not null then target=(d->>'revealAt')::double precision+6000;
 elsif ms<(d->>'starts')::double precision then target=(d->>'starts')::double precision;
 else step=(r->>'duration')::double precision*200;
  target=least((d->>'ends')::double precision,(d->>'starts')::double precision+(floor((ms-(d->>'starts')::double precision)/step)+1)*step);
 end if;
 return to_timestamp(target/1000);
end $$;

-- Reuse the tested relational projection for each isolated document.
create trigger project_document before insert or update of payload on blurt_private.game_documents
 for each row execute function blurt_private.project_state();
create function blurt_private.document_changed() returns trigger
language plpgsql security invoker set search_path='' as $$
declare r jsonb; d jsonb; m jsonb; rid text;
begin
 if new.scope like 'room:%' then
  r=new.payload->'rooms'->split_part(new.scope,':',2); d=r->'roundData';
  if r->>'matchId' is not null and d is not null and d<>'null'::jsonb then
   insert into blurt_private.matches values((r->>'matchId')::uuid,r->>'code',jsonb_build_object('rounds',r->'rounds','duration',r->'duration','category',r->'category'),to_timestamp((r->>'matchStarted')::double precision/1000),case when r->>'status'='finished' then now() else null end)
   on conflict(id) do update set finished_at=coalesce(blurt_private.matches.finished_at,excluded.finished_at);
   rid=(r->>'code')||':'||(d->>'starts');
   update blurt_private.rounds set match_id=(r->>'matchId')::uuid where id=rid;
   for m in select value from jsonb_array_elements(r->'members') where not (value->>'spectator')::boolean loop
    insert into blurt_private.round_players values(rid,m->>'id',case when d->'solved' ? (m->>'id') then 'solved' when d->>'revealAt' is not null then 'unsolved' else 'active' end,case when d->'solved' ? (m->>'id') then 6-((d->'solved'->>(m->>'id'))::int/100) else null end,coalesce((d->'solved'->>(m->>'id'))::int,0))
    on conflict(round_id,player_id) do update set status=excluded.status,solved_stage=excluded.solved_stage,points=excluded.points;
   end loop;
  end if;
  perform realtime.send(jsonb_build_object('revision',new.revision),'changed',new.scope,true);
 end if;
 update blurt_private.players set auth_user_id=id::uuid where auth_user_id is null and id ~ '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$';
 return null;
end $$;
create trigger document_changed after insert or update on blurt_private.game_documents for each row execute function blurt_private.document_changed();

create function public.blurt_read_document(p_scope text) returns jsonb
language sql security invoker set search_path='' as $$
 select jsonb_build_object('now',floor(extract(epoch from clock_timestamp())*1000),'revision',coalesce(d.revision,0),'payload',coalesce(d.payload,'{"players":{},"daily":{},"rooms":{}}'::jsonb))
 from (select 1) base left join blurt_private.game_documents d on d.scope=p_scope;
$$;
create function public.blurt_commit_document(p_scope text,p_revision bigint,p_payload jsonb) returns boolean
language plpgsql security invoker set search_path='' as $$
declare n integer; r jsonb; deadline timestamptz;
begin
 if octet_length(p_payload::text)>262144 then raise exception 'Document too large'; end if;
 r=p_payload->'rooms'->split_part(p_scope,':',2);
 if p_scope like 'room:%' and r is not null then deadline=blurt_private.next_deadline(r); end if;
 if p_revision=0 then
  insert into blurt_private.game_documents(scope,payload,next_at) values(p_scope,p_payload,deadline) on conflict do nothing;
 else
  update blurt_private.game_documents set payload=p_payload,revision=revision+1,next_at=deadline where scope=p_scope and revision=p_revision;
 end if;
 get diagnostics n=row_count;return n=1;
end $$;
create function public.blurt_rate_limit(p_actor text,p_bucket text,p_limit integer,p_window integer) returns boolean
language plpgsql security invoker set search_path='' as $$
declare stamp bigint := floor(extract(epoch from clock_timestamp())/p_window)*p_window; n integer;
begin
 insert into blurt_private.rate_limits values(p_actor,p_bucket,stamp,1)
 on conflict(actor,bucket,window_start) do update set count=blurt_private.rate_limits.count+1 where blurt_private.rate_limits.count<p_limit;
 get diagnostics n=row_count;return n=1;
end $$;

-- Authenticated clients only receive invalidation hints for rooms they belong to.
-- The definer helper is private, checks auth.uid(), and returns no game state.
create function blurt_private.can_receive_room(topic text) returns boolean
language sql stable security definer set search_path='' as $$
 select auth.uid() is not null and exists(select 1 from blurt_private.room_members m join blurt_private.rooms r on r.code=m.room_code where topic='room:'||m.room_code and m.player_id=auth.uid()::text and r.expires_at>now());
$$;
revoke all on function blurt_private.can_receive_room(text) from public;
grant usage on schema blurt_private to authenticated,service_role;
grant execute on function blurt_private.can_receive_room(text) to authenticated;
create policy blurt_room_receive on realtime.messages for select to authenticated using(blurt_private.can_receive_room(realtime.topic()));

-- The database scheduler owns transitions even with no connected browsers.
create function blurt_private.advance_due_rooms() returns integer
language plpgsql security definer set search_path='' as $$
declare doc record; r jsonb; d jsonb; ms bigint; reveal bigint; starts bigint; code text; picked text; pool text[]; unused text[]; chosen_host text; iterations integer; processed integer:=0;
begin
 ms=floor(extract(epoch from clock_timestamp())*1000);
 for doc in select * from blurt_private.game_documents where scope like 'room:%' and next_at<=clock_timestamp() order by next_at limit 100 for update skip locked loop
  code=split_part(doc.scope,':',2);r=doc.payload->'rooms'->code;
  if (r->>'expires')::bigint<=ms then
   delete from blurt_private.room_members where room_code=code;
   delete from blurt_private.game_documents where scope=doc.scope;continue;
  end if;
  if not exists(select 1 from jsonb_array_elements(r->'members') m where m->>'id'=r->>'host' and (m->>'seen')::bigint>ms-45000) then
   select m->>'id' into chosen_host from jsonb_array_elements(r->'members') m where (m->>'seen')::bigint>ms-45000 order by (m->>'joined')::bigint limit 1;
   if chosen_host is not null then r=jsonb_set(r,'{host}',to_jsonb(chosen_host)); end if;
  end if;
  iterations=0;
  while r->>'status'='playing' and iterations<16 loop
   iterations=iterations+1;d=r->'roundData';
   if d->>'revealAt' is null then
    if (d->>'ends')::bigint>ms then exit; end if;
    d=jsonb_set(d,'{revealAt}',d->'ends');r=jsonb_set(r,'{roundData}',d);
   end if;
   reveal=(d->>'revealAt')::bigint;
   if reveal+6000>ms then exit; end if;
   if (r->>'round')::int>=(r->>'rounds')::int then r=jsonb_set(r,'{status}','"finished"');exit; end if;
   select array_agg(id) into pool from blurt_private.puzzles where status='active' and (r->>'category'='All pictures' or category=r->>'category');
   select array_agg(x) into unused from unnest(pool) x where not (r->'used' ? x);
   if cardinality(unused) is null or cardinality(unused)=0 then unused=pool;r=jsonb_set(r,'{repeat}','true');end if;
   if cardinality(unused) is null then r=jsonb_set(r,'{status}','"finished"');exit;end if;
   picked=unused[1+floor(random()*cardinality(unused))::int];starts=reveal+9000;
   r=jsonb_set(r,'{used}',(r->'used')||to_jsonb(picked));
   r=jsonb_set(r,'{round}',to_jsonb((r->>'round')::int+1));
   r=jsonb_set(r,'{roundData}',jsonb_build_object('puzzle',picked,'starts',starts,'ends',starts+(r->>'duration')::bigint*1000,'guesses','[]'::jsonb,'solved','{}'::jsonb));
  end loop;
  update blurt_private.game_documents set payload=jsonb_set(doc.payload,array['rooms',code],r),revision=revision+1,next_at=blurt_private.next_deadline(r) where scope=doc.scope;
  processed=processed+1;
 end loop;return processed;
end $$;
revoke all on function blurt_private.advance_due_rooms() from public,anon,authenticated;
revoke all on all tables in schema blurt_private from anon,authenticated;
grant all on all tables in schema blurt_private to service_role;
grant execute on all functions in schema blurt_private to service_role;
revoke all on function public.blurt_read_document(text),public.blurt_commit_document(text,bigint,jsonb),public.blurt_rate_limit(text,text,integer,integer) from public,anon,authenticated;
grant execute on function public.blurt_read_document(text),public.blurt_commit_document(text,bigint,jsonb),public.blurt_rate_limit(text,text,integer,integer) to service_role;

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('blurt-puzzles','blurt-puzzles',false,1048576,array['image/webp']) on conflict(id) do nothing;
-- No client Storage policies: only the authorized Edge function reads objects.
create extension if not exists pg_cron;
select cron.schedule('blurt-round-transitions','1 second','select blurt_private.advance_due_rooms()');
select cron.schedule('blurt-rate-limit-cleanup','17 * * * *','delete from blurt_private.rate_limits where window_start<extract(epoch from now())-86400');
create table blurt_private.content_releases(version text primary key, installed_at timestamptz not null default now());
alter table blurt_private.content_releases enable row level security;
grant all on blurt_private.content_releases to service_role;
create function public.blurt_seed_catalog(p_version text,p_puzzles jsonb) returns void language plpgsql security invoker set search_path='' as $$
declare p jsonb; a text; stage integer;
begin
 if exists(select 1 from blurt_private.content_releases where version=p_version) then return;end if;
 perform pg_advisory_xact_lock(281975442);
 for p in select value from jsonb_array_elements(p_puzzles) loop
  insert into blurt_private.puzzles(id,canonical_answer,category) values(p->>'id',p->>'answer',p->>'category') on conflict(id) do nothing;
  for a in select jsonb_array_elements_text((p->'aliases')||jsonb_build_array(p->>'answer')) loop
   insert into blurt_private.puzzle_answers values(p->>'id',a) on conflict do nothing;
  end loop;
  for stage in 1..6 loop
   insert into blurt_private.puzzle_assets values(p->>'id',stage,'v1/'||(p->>'id')||'-'||stage||'.webp') on conflict do nothing;
  end loop;
 end loop;
 insert into blurt_private.content_releases values(p_version,now()) on conflict do nothing;
end $$;
revoke all on function public.blurt_seed_catalog(text,jsonb) from public,anon,authenticated;
grant execute on function public.blurt_seed_catalog(text,jsonb) to service_role;
create function public.blurt_player_stats(p_player text) returns jsonb language sql stable security invoker set search_path='' as $$
 select jsonb_build_object('played',count(*) filter(where status='finished'),'won',count(*) filter(where solved_stage is not null),'best',min(solved_stage)) from blurt_private.daily_runs where player_id=p_player;
$$;
revoke all on function public.blurt_player_stats(text) from public,anon,authenticated;
grant execute on function public.blurt_player_stats(text) to service_role;

-- Pin each day's official puzzle once, independent of content deployments.
create function public.blurt_daily_puzzle(p_day integer) returns text
language plpgsql security invoker set search_path='' as $$
declare chosen text; total integer;
begin
 select puzzle_id into chosen from blurt_private.daily_puzzles where day=p_day;
 if chosen is not null then return chosen;end if;
 select count(*) into total from blurt_private.puzzles where status='active';
 if total=0 then raise exception 'No active puzzles';end if;
 select id into chosen from blurt_private.puzzles where status='active' order by id offset mod(p_day,total) limit 1;
 insert into blurt_private.daily_puzzles values(p_day,chosen,to_timestamp(p_day::double precision*86400),to_timestamp((p_day::double precision+1)*86400)) on conflict(day) do nothing;
 select puzzle_id into chosen from blurt_private.daily_puzzles where day=p_day;
 return chosen;
end $$;
revoke all on function public.blurt_daily_puzzle(integer) from public,anon,authenticated;
grant execute on function public.blurt_daily_puzzle(integer) to service_role;
create index daily_runs_player_day on blurt_private.daily_runs(player_id,day desc);
create index daily_puzzles_puzzle on blurt_private.daily_puzzles(puzzle_id);
create index rooms_host on blurt_private.rooms(host_player_id);
create index rounds_puzzle on blurt_private.rounds(puzzle_id);
create index puzzles_pool on blurt_private.puzzles(category,status);
-- Explicit backend policies document the deny-by-default client access model.
do $$declare t record;begin
 for t in select tablename from pg_tables where schemaname='blurt_private' loop
  execute format('create policy backend_only on blurt_private.%I for all to service_role using(true) with check(true)',t.tablename);
 end loop;
end $$;
revoke all on schema cron from anon,authenticated;

-- A BEFORE INSERT trigger runs even for INSERT ... ON CONFLICT DO NOTHING.
-- Guard the missing-row case before firing projections, so a losing first-write
-- cannot change normalized results or membership. Locks are per document.
create or replace function public.blurt_commit_document(p_scope text,p_revision bigint,p_payload jsonb) returns boolean
language plpgsql security invoker set search_path='' as $$
declare n integer; r jsonb; deadline timestamptz;
begin
 if octet_length(p_payload::text)>262144 then raise exception 'Document too large';end if;
 perform pg_advisory_xact_lock(hashtextextended('blurt:'||p_scope,0));
 if p_revision=0 and exists(select 1 from blurt_private.game_documents where scope=p_scope) then return false;end if;
 r=p_payload->'rooms'->split_part(p_scope,':',2);
 if p_scope like 'room:%' and r is not null then deadline=blurt_private.next_deadline(r);end if;
 if p_revision=0 then
  insert into blurt_private.game_documents(scope,payload,next_at) values(p_scope,p_payload,deadline);
 else
  update blurt_private.game_documents set payload=p_payload,revision=revision+1,next_at=deadline where scope=p_scope and revision=p_revision;
 end if;
 get diagnostics n=row_count;return n=1;
end $$;
-- Keep high-frequency scheduler diagnostics bounded without deleting game data.
select cron.schedule('blurt-job-history-cleanup','23 * * * *','delete from cron.job_run_details where jobid in (select jobid from cron.job where jobname like ''blurt-%'') and end_time<now()-interval ''2 days''');

-- Solo games use separate actor-bound documents and retain normalized run history.
create table blurt_private.solo_sessions (
 id uuid primary key, player_id text not null references blurt_private.players(id),
 mode text not null check(mode in ('FREE','FLASH')), started_at timestamptz not null,
 ends_at timestamptz, finished boolean not null, score integer not null check(score>=0),
 solved integer not null check(solved>=0), best integer not null check(best>=0)
);
create index solo_sessions_player on blurt_private.solo_sessions(player_id,started_at desc);
create table blurt_private.solo_rounds (
 session_id uuid references blurt_private.solo_sessions(id) on delete cascade,
 position integer not null, puzzle_id text not null, done boolean not null,
 solved boolean not null, points integer not null check(points between 0 and 1500),
 primary key(session_id,position)
);
create table blurt_private.solo_guesses (
 session_id uuid not null, position integer not null, stage integer not null check(stage between 1 and 5),
 text text not null, correct boolean not null,
 primary key(session_id,position,stage),
 foreign key(session_id,position) references blurt_private.solo_rounds(session_id,position) on delete cascade
);
alter table blurt_private.solo_sessions enable row level security;
alter table blurt_private.solo_rounds enable row level security;
alter table blurt_private.solo_guesses enable row level security;
revoke all on blurt_private.solo_sessions, blurt_private.solo_rounds, blurt_private.solo_guesses from public,anon,authenticated;
grant all on blurt_private.solo_sessions, blurt_private.solo_rounds, blurt_private.solo_guesses to service_role;
create function blurt_private.solo_deadline() returns trigger language plpgsql set search_path='' as $$
declare r jsonb;
begin
 if new.scope like 'solo:%' then
  r=new.payload->'solo'->(split_part(new.scope,':',2)||':'||split_part(new.scope,':',3));
  new.next_at=case when r->>'mode'='FLASH' and not (r->>'finished')::boolean then to_timestamp((r->>'ends')::double precision/1000) else null end;
 end if;
 return new;
end $$;
create trigger solo_deadline before insert or update on blurt_private.game_documents for each row execute function blurt_private.solo_deadline();
create function blurt_private.project_solo() returns trigger language plpgsql set search_path='' as $$
declare r jsonb; c jsonb; g jsonb; pid text;
begin
 if new.scope not like 'solo:%' then return null;end if;
 pid=split_part(new.scope,':',2);
 r=new.payload->'solo'->(pid||':'||split_part(new.scope,':',3));
 if r is null then return null;end if;
 c=r->'current';
 insert into blurt_private.solo_sessions values((r->>'id')::uuid,pid,r->>'mode',to_timestamp((r->>'started')::double precision/1000),to_timestamp((r->>'ends')::double precision/1000),(r->>'finished')::boolean,(r->>'score')::int,(r->>'solved')::int,(r->>'best')::int)
 on conflict(id) do update set finished=excluded.finished,score=excluded.score,solved=excluded.solved,best=excluded.best;
 insert into blurt_private.solo_rounds values((r->>'id')::uuid,(r->>'position')::int,c->>'puzzle',(c->>'done')::boolean,(c->>'solved')::boolean,(c->>'points')::int)
 on conflict(session_id,position) do update set done=excluded.done,solved=excluded.solved,points=excluded.points;
 for g in select value from jsonb_array_elements(c->'guesses') loop
  insert into blurt_private.solo_guesses values((r->>'id')::uuid,(r->>'position')::int,(g->>'stage')::int,g->>'text',(g->>'correct')::boolean) on conflict do nothing;
 end loop;
 return null;
end $$;
create trigger solo_project after insert or update on blurt_private.game_documents for each row execute function blurt_private.project_solo();
create function blurt_private.advance_due_solos() returns void language plpgsql security definer set search_path='' as $$
declare doc record; k text; r jsonb;
begin
 for doc in select * from blurt_private.game_documents where scope like 'solo:%' and next_at<=clock_timestamp() order by next_at limit 100 for update skip locked loop
  k=split_part(doc.scope,':',2)||':'||split_part(doc.scope,':',3);r=doc.payload->'solo'->k;
  r=jsonb_set(r,'{finished}','true'::jsonb);
  update blurt_private.game_documents set payload=jsonb_set(doc.payload,array['solo',k],r),revision=revision+1,next_at=null where scope=doc.scope;
 end loop;
end $$;
revoke all on function blurt_private.solo_deadline(),blurt_private.project_solo(),blurt_private.advance_due_solos() from public,anon,authenticated;
grant execute on function blurt_private.solo_deadline(),blurt_private.project_solo(),blurt_private.advance_due_solos() to service_role;
select cron.schedule('blurt-solo-timeouts','1 second','select blurt_private.advance_due_solos()');

